import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.DWopfgZq.js";var i=JSON.parse(`{"title":"概述","description":"","frontmatter":{},"headers":[],"relativePath":"feature/intro.md","filePath":"feature/intro.md","lastUpdated":1792240695000}`),a={name:`feature/intro.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h1><p>太郎提供扩展、Windows、macOS 和 Android 客户端。文档中的部分截图和 GIF 来自旧版扩展，按钮外观和位置可能与当前版本不同，请以对应平台的入口和下文说明为准。</p><h2 id="各端入口与差异" tabindex="-1">各端入口与差异 <a class="header-anchor" href="#各端入口与差异" aria-label="Permalink to “各端入口与差异”">​</a></h2><table tabindex="0"><thead><tr><th>客户端</th><th>功能入口</th></tr></thead><tbody><tr><td>Chrome 扩展</td><td>浏览器侧边栏或窗口栏</td></tr><tr><td>Windows / macOS</td><td>主窗口右侧功能区，底部头像菜单打开账号、设置与帮助</td></tr><tr><td>Android</td><td>底部太郎图标打开菜单，进入功能面板；面板可收藏到底部工具栏</td></tr></tbody></table><p>掉落统计、配置查询与上传等云端功能需要<a href="./info#登录与注册">登录太郎账号</a>。有效会员可自动同步部分配置；本地数据展示仍可通过游客模式使用。</p><p>移动端目前没有抽卡模拟、标记玩家管理、接战和独立战斗浮窗入口；用户信息不展示友招，队伍截图与配置对比、神器规则操作等工具也有差异，详见对应功能页面。桌面端与移动端均可使用<a href="./setting#用户脚本">用户脚本</a>，桌面端另有<a href="./setting#游戏代理">游戏代理</a>。</p><p>以下侧边栏和窗口栏说明仅适用于扩展。</p><h2 id="如何打开插件面板" tabindex="-1">如何打开插件面板 <a class="header-anchor" href="#如何打开插件面板" aria-label="Permalink to “如何打开插件面板”">​</a></h2><p>插件面板，也就是浏览器侧边栏有两种打开方式。一种是点击导航栏中的太郎图标</p><p><img src="/tarou-docs/assets/img/intro-img1.png" alt="alt text" width="860" height="99"></p><p>另一种是在游戏页面中打开右键菜单，选择开启侧边栏</p><p><img src="/tarou-docs/assets/img/intro-img2.png" alt="alt text" width="535" height="537"></p><p>为了避免一些冲突问题，侧边栏只能开启一个，已经开启侧边栏的情况下在新标签页开启侧边栏会自动关闭。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>浏览器的应用模式，也就是APP模式下不支持使用侧边栏，点击会没反应或者闪退。</p></div><h2 id="如何调整侧边栏" tabindex="-1">如何调整侧边栏 <a class="header-anchor" href="#如何调整侧边栏" aria-label="Permalink to “如何调整侧边栏”">​</a></h2><p>侧边栏可以调整位置和宽度。位置需要在浏览器自身的设置里选择，可以让其显示在浏览器左侧或右侧。</p><p><img src="/tarou-docs/assets/img/intro-img3.png" alt="alt text" width="832" height="891"></p><p>拖拽浏览器与侧边栏的边界可以调整侧边栏的宽度。</p><p><img src="/tarou-docs/assets/img/intro-img4.gif" alt="alt text" width="882" height="522"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>因为插件样式都是按照侧边栏的最小宽度来设计的，但不同浏览器侧边栏的最小宽度并不统一。为了保证统一的展示效果，同时也为了解决有部分人觉得页面太小看不清的问题。改变侧边栏宽度会同时按比例对页面进行缩放，保证布局的一致性。</p></div><h2 id="窗口栏" tabindex="-1">窗口栏 <a class="header-anchor" href="#窗口栏" aria-label="Permalink to “窗口栏”">​</a></h2><p>右键菜单中还有个选项是开启窗口栏。窗口栏的功能与侧边栏完全一致，只不过是在新窗口打开，解决浏览器应用(APP)模式无法使用侧边栏的问题，窗口栏和侧边栏只能打开一种。</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};